INSERT INTO modules (id, unit_id, order_index, slug, title, description, is_published) VALUES
('00000001-0000-0000-0000-000000000001', '00000000-0000-0000-0001-000000000001', 1, 'alfabeto-y-sonidos', '{"es": "El Alfabeto y Sonidos", "en": "The Alphabet and Sounds"}'::jsonb, '{"es": "Aprende el alfabeto inglés, los sonidos de las vocales y consonantes, y cómo deletrear palabras comunes.", "en": "Learn the English alphabet, vowel and consonant sounds, and how to spell common words."}'::jsonb, true);
INSERT INTO modules (id, unit_id, order_index, slug, title, description, is_published) VALUES
('00000001-0000-0000-0000-000000000002', '00000000-0000-0000-0001-000000000001', 2, 'saludos-y-presentaciones', '{"es": "Saludos y Presentaciones", "en": "Greetings and Introductions"}'::jsonb, '{"es": "Aprende a saludar, presentarte, preguntar por otras personas y usar frases de cortesía en inglés.", "en": "Learn to greet, introduce yourself, ask about others, and use polite phrases in English."}'::jsonb, true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0001-000000000001', '00000001-0000-0000-0000-000000000001', '00000000-0000-0000-0001-000000000001', 1, 'las-vocales-del-ingles', '{"es": "Las Vocales del Inglés", "en": "English Vowels"}'::jsonb, '{"es": "Aprende los sonidos de las cinco vocales en inglés: A, E, I, O, U, y la diferencia entre sonidos cortos y largos.", "en": "Learn the sounds of the five vowels in English: A, E, I, O, U, and the difference between short and long sounds."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "En inglés, las vocales son A, E, I, O, U — igual que en español. Sin embargo, cada vocal puede tener DOS sonidos diferentes: un sonido CORTO y un sonido LARGO. Esta es una de las diferencias más importantes entre el inglés y el español, y dominarla te ayudará a pronunciar y entender el inglés mucho mejor.", "sections": [{"type": "explanation", "title": "VOCALES CORTAS", "text": "Las vocales cortas son sonidos breves y relajados. Se encuentran generalmente en sílabas cerradas (que terminan en consonante). Por ejemplo: la A corta suena como en ''cat'' (gato), la E corta suena como en ''bed'' (cama), la I corta suena como en ''sit'' (sentarse), la O corta suena como en ''hot'' (caliente), y la U corta suena como en ''cup'' (taza)."}, {"type": "explanation", "title": "VOCALES LARGAS", "text": "Las vocales largas suenan igual que el nombre de la letra en el alfabeto inglés. Se encuentran generalmente en sílabas abiertas o cuando la palabra termina en E silenciosa. Por ejemplo: la A larga suena como en ''cake'' (pastel), la E larga suena como en ''feet'' (pies), la I larga suena como en ''bike'' (bicicleta), la O larga suena como en ''home'' (hogar), y la U larga suena como en ''cube'' (cubo)."}, {"type": "table", "title": "COMPARACIÓN DE VOCALES CORTAS Y LARGAS", "headers": ["Vocal", "Sonido Corto", "Ejemplo Corto", "Sonido Largo", "Ejemplo Largo"], "rows": [["A", "/æ/", "cat (gato)", "/eɪ/", "cake (pastel)"], ["E", "/ɛ/", "bed (cama)", "/iː/", "feet (pies)"], ["I", "/ɪ/", "sit (sentarse)", "/aɪ/", "bike (bicicleta)"], ["O", "/ɒ/", "hot (caliente)", "/oʊ/", "home (hogar)"], ["U", "/ʌ/", "cup (taza)", "/juː/", "cube (cubo)"]]}, {"type": "examples", "title": "EJEMPLOS EN CONTEXTO", "items": [{"label": "A corta", "en": "The cat sat on the mat.", "es": "El gato se sentó en el tapete."}, {"label": "A larga", "en": "I ate a cake today.", "es": "Hoy comí un pastel."}, {"label": "I corta", "en": "The fish is in the dish.", "es": "El pez está en el plato."}, {"label": "O larga", "en": "I go home alone.", "es": "Voy a casa solo."}]}, {"type": "note", "variant": "tip", "text": "Un truco muy útil: cuando una palabra termina en E silenciosa (como ''cake'', ''bike'', ''home''), la vocal anterior generalmente tiene sonido LARGO. Esta regla se llama la ''magic E'' o E mágica en inglés."}]}'::jsonb, true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0001-000000000002', '00000001-0000-0000-0000-000000000001', '00000000-0000-0000-0001-000000000001', 2, 'las-consonantes', '{"es": "Las Consonantes", "en": "Consonants"}'::jsonb, '{"es": "Aprende los sonidos de las consonantes en inglés, con énfasis en TH, W, J/Y, y la confusión V/B para hispanohablantes.", "en": "Learn English consonant sounds, with focus on TH, W, J/Y, and the V/B confusion for Spanish speakers."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "Las consonantes del inglés presentan varios desafíos para los hispanohablantes. Algunos sonidos simplemente no existen en español, mientras que otros suenan parecido pero son diferentes. En esta lección nos concentramos en los sonidos consonánticos que más confunden a los hispanohablantes.", "sections": [{"type": "explanation", "title": "EL SONIDO TH", "text": "El sonido TH no existe en español y es uno de los más difíciles para nosotros. Hay dos versiones: TH suave (''voiced'') como en ''the'', ''this'', ''that'' — debes colocar la lengua entre los dientes y hacer vibrar las cuerdas vocales. Y TH fuerte (''voiceless'') como en ''think'', ''three'', ''tooth'' — misma posición de lengua, pero sin vibración. Mucha gente lo sustituye por S o D, pero con práctica se puede dominar."}, {"type": "explanation", "title": "V/B Y W — CONFUSIONES COMUNES", "text": "En español, la V y la B suenan casi igual. En inglés son completamente distintos: B se pronuncia juntando los labios (como en español), mientras que V se pronuncia mordiendo el labio inferior con los dientes superiores. La W es otro sonido que no existe en español — se hace redondeando los labios como si fueras a soplar una vela, como en ''water'', ''wood'', ''woman''. No es una V ni una U — es un sonido labial suave."}, {"type": "table", "title": "CONSONANTES DIFÍCILES PARA HISPANOHABLANTES", "headers": ["Sonido", "Símbolo", "Ejemplo", "Truco para pronunciar"], "rows": [["TH suave", "/ð/", "the, this, that", "Lengua entre dientes + vibración"], ["TH fuerte", "/θ/", "think, three", "Lengua entre dientes, sin vibración"], ["W", "/w/", "water, wood", "Labios redondeados, como soplar"], ["V", "/v/", "very, voice", "Dientes superiores en labio inferior"], ["J inglesa", "/dʒ/", "jump, job", "Como ''ch'' español pero más suave"]]}, {"type": "examples", "title": "EJEMPLOS COMPARATIVOS", "items": [{"label": "TH vs S/D", "en": "Think (piensa) — NOT ''sink'' or ''dink''", "es": "El TH de ''think'' no es S ni D"}, {"label": "V vs B", "en": "Very (muy) — NOT ''berry''", "es": "La V vibra con los dientes, la B con los labios"}, {"label": "W", "en": "Water (agua) — NOT ''gwater'' or ''vater''", "es": "La W no es V ni GU en inglés"}]}, {"type": "note", "variant": "tip", "text": "Para practicar el TH, prueba este trabalenguas: ''The thirty-three thieves thought that they thrilled the throne.'' Practica despacio primero, luego aumenta la velocidad gradualmente."}]}'::jsonb, true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0001-000000000003', '00000001-0000-0000-0000-000000000001', '00000000-0000-0000-0001-000000000001', 3, 'spelling-deletrear-en-ingles', '{"es": "Spelling: Deletrear en Inglés", "en": "Spelling in English"}'::jsonb, '{"es": "Aprende cómo deletrear tu nombre y palabras comunes en inglés, y los nombres de las letras del alfabeto inglés.", "en": "Learn how to spell your name and common words in English, and the names of English alphabet letters."}'::jsonb, 'theory_practice', 20, 15, '{"intro": "Deletrear en inglés (''to spell'') es una habilidad esencial. Necesitarás deletrear tu nombre al registrarte en hoteles, al dar tu correo electrónico, o al comunicarte por teléfono. El alfabeto inglés tiene 26 letras, y cada una tiene un nombre específico que debes memorizar.", "sections": [{"type": "explanation", "title": "EL ALFABETO INGLÉS", "text": "Las 26 letras del alfabeto inglés se pronuncian de manera muy diferente a como suenan en español. Por ejemplo, la letra ''E'' en inglés se llama /iː/ (como la I larga española), la ''I'' se llama /aɪ/ (como ''ay''), la ''G'' se llama /dʒiː/, y la ''J'' se llama /dʒeɪ/. Es importante aprender el NOMBRE de cada letra para poder deletrear correctamente."}, {"type": "table", "title": "EL ALFABETO INGLÉS CON PRONUNCIACIÓN", "headers": ["Letra", "Nombre", "Pronunciación aproximada"], "rows": [["A", "ay", "/eɪ/"], ["B", "bee", "/biː/"], ["C", "see", "/siː/"], ["D", "dee", "/diː/"], ["E", "ee", "/iː/"], ["F", "ef", "/ɛf/"], ["G", "gee", "/dʒiː/"], ["H", "aitch", "/eɪtʃ/"], ["I", "eye", "/aɪ/"], ["J", "jay", "/dʒeɪ/"], ["K", "kay", "/keɪ/"], ["L", "el", "/ɛl/"], ["M", "em", "/ɛm/"], ["N", "en", "/ɛn/"], ["O", "oh", "/oʊ/"], ["P", "pee", "/piː/"], ["Q", "cue", "/kjuː/"], ["R", "ar", "/ɑːr/"], ["S", "ess", "/ɛs/"], ["T", "tee", "/tiː/"], ["U", "you", "/juː/"], ["V", "vee", "/viː/"], ["W", "double-you", "/ˈdʌbəl juː/"], ["X", "ex", "/ɛks/"], ["Y", "why", "/waɪ/"], ["Z", "zee", "/ziː/"]]}, {"type": "explanation", "title": "CÓMO PREGUNTAR Y DELETREAR", "text": "Para pedir a alguien que deletree algo, pregunta: ''How do you spell that?'' (¿Cómo se deletrea eso?) o ''Can you spell that for me?'' (¿Puedes deletrearlo?). Para decir que vas a deletrear algo, di: ''It''s spelled...'' seguido de las letras. Por ejemplo: ''My name is Ana. It''s spelled A-N-A.''"}, {"type": "examples", "title": "EJEMPLOS DE DELETREO", "items": [{"label": "Nombre", "en": "My name is Carlos. C-A-R-L-O-S.", "es": "Mi nombre es Carlos. C-A-R-L-O-S."}, {"label": "Email", "en": "My email is... Can you spell that? Sure: J-U-A-N at gmail dot com.", "es": "Mi correo es... ¿Puedes deletrearlo? Claro: J-U-A-N en gmail punto com."}, {"label": "Pregunta", "en": "How do you spell ''necessary''?", "es": "¿Cómo se escribe ''necessary''?"}]}, {"type": "note", "variant": "tip", "text": "Cuando hay letras que suenan similar (como B y D, o M y N), los anglohablantes usan nombres de ciudades o palabras para clarificar: ''B for Boston'' o ''D for Delta''. Puedes usar países o nombres que conozcas."}]}'::jsonb, true);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0001-000000000004', '00000001-0000-0000-0000-000000000001', '00000000-0000-0000-0001-000000000001', 4, 'sonidos-dificiles-para-hispanohablantes', '{"es": "Sonidos Difíciles para Hispanohablantes", "en": "Difficult Sounds for Spanish Speakers"}'::jsonb, '{"es": "Practica los sonidos más difíciles del inglés para hispanohablantes: SH, CH, NG, y la R inglesa.", "en": "Practice the most difficult English sounds for Spanish speakers: SH, CH, NG, and the English R."}'::jsonb, 'theory_practice', 25, 20, '{"intro": "Algunos sonidos del inglés son especialmente difíciles para los hispanohablantes porque no existen en español. En esta lección nos enfocamos en cuatro de los más desafiantes: SH, CH, NG, y la R inglesa. Con práctica y las técnicas correctas, puedes dominar estos sonidos.", "sections": [{"type": "explanation", "title": "EL SONIDO SH", "text": "El sonido SH (como en ''she'', ''shop'', ''fish'') no existe en español estándar. Para producirlo, coloca los labios ligeramente hacia adelante (como si fueras a dar un beso) y sopla aire entre la lengua y el paladar. Es un sonido suave y continuo, como cuando alguien dice ''shhhh'' para pedir silencio. No es la S española ni la CH española — es un sonido intermedio y suave."}, {"type": "explanation", "title": "SH VS CH Y LA R INGLESA", "text": "El sonido CH en inglés (''chair'', ''church'', ''chicken'') es similar al CH español, pero más enfático. La diferencia clave con SH es que CH tiene una pequeña explosión al principio. La R inglesa es quizás el sonido más diferente: en inglés la R NO vibra como en español. Se produce curvando la lengua hacia atrás sin tocar el paladar. El sonido es más parecido a una vocal suave que a la R española vibrante."}, {"type": "explanation", "title": "EL SONIDO NG", "text": "El sonido NG (como en ''sing'', ''ring'', ''morning'') es la terminación más común en inglés para los gerundios (-ing) y muchas palabras. Para producirlo, la parte posterior de la lengua toca el paladar suave (velo) y el aire sale por la nariz. Es similar al sonido N antes de G o K en español (como en ''banco'' o ''tengo''), pero al final de la palabra."}, {"type": "table", "title": "GUÍA DE SONIDOS DIFÍCILES", "headers": ["Sonido", "Símbolo IPA", "Ejemplos", "Cómo se produce"], "rows": [["SH", "/ʃ/", "she, shop, fish, wash", "Labios al frente, lengua al paladar, aire suave"], ["CH", "/tʃ/", "chair, church, chicken", "Como SH pero con explosión inicial"], ["NG", "/ŋ/", "sing, ring, morning, going", "Lengua atrás en paladar, aire por nariz"], ["R inglesa", "/r/", "red, rain, car, more", "Lengua curvada hacia atrás, sin vibración"]]}, {"type": "examples", "title": "EJEMPLOS CON CONTEXTO", "items": [{"label": "SH", "en": "She sells seashells by the seashore.", "es": "Ella vende conchas en la orilla del mar."}, {"label": "CH", "en": "The chicken in the chair is cheerful.", "es": "El pollo en la silla está alegre."}, {"label": "NG", "en": "I am singing and dancing in the morning.", "es": "Estoy cantando y bailando por la mañana."}, {"label": "R inglesa", "en": "The red car drives far.", "es": "El auto rojo maneja lejos."}]}, {"type": "note", "variant": "tip", "text": "Para la R inglesa, intenta decir la palabra sin tocar ninguna parte de tu boca con la lengua — solo curva la lengua hacia atrás. Muchos estudiantes encuentran útil practicar con palabras como ''butter'', ''water'', y ''never'' donde la R está al final o en medio de la palabra."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0001-0001-000000000001', '00000002-0000-0000-0001-000000000001', 1, 'flashcard', '{"text": "cat", "subtext": "Vocal A corta /æ/"}'::jsonb, '{"text": "gato", "phonetic": "/kæt/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0001-0002-000000000001', '00000002-0000-0000-0001-000000000001', 2, 'flashcard', '{"text": "cake", "subtext": "Vocal A larga /eɪ/ — nota la E final silenciosa"}'::jsonb, '{"text": "pastel", "phonetic": "/keɪk/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0001-0003-000000000001', '00000002-0000-0000-0001-000000000001', 3, 'multiple_choice', '{"text": "¿Cuál es la diferencia entre ''cat'' y ''cake''?"}'::jsonb, '{"text": "La A de ''cat'' es corta /æ/ y la A de ''cake'' es larga /eɪ/"}'::jsonb, '["Las dos tienen exactamente el mismo sonido de A", "''cat'' tiene A larga y ''cake'' tiene A corta", "La diferencia está en las consonantes, no en la vocal"]'::jsonb, '{"es": "La E final silenciosa en ''cake'' hace que la A sea larga /eɪ/. En ''cat'' no hay E final, así que la A es corta /æ/. Esta es la regla de la ''magic E''."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0001-0004-000000000001', '00000002-0000-0000-0001-000000000001', 4, 'multiple_choice', '{"text": "¿Qué vocal tiene sonido LARGO en la palabra ''bike''?"}'::jsonb, '{"text": "La I, que suena /aɪ/ como en ''eye''"}'::jsonb, '["La B, que es consonante y no tiene sonido vocal", "La E, aunque es silenciosa al final", "La I tiene sonido corto /ɪ/ como en ''sit''"]'::jsonb, '{"es": "En ''bike'', la I tiene sonido largo /aɪ/ gracias a la E final silenciosa. La regla magic E: consonante + vocal + consonante + E = vocal larga."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0001-0005-000000000001', '00000002-0000-0000-0001-000000000001', 5, 'fill_blank', '{"text": "I sleep in a ___. (cama en inglés)"}'::jsonb, '{"text": "bed", "accepted": ["bed"]}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0001-0006-000000000001', '00000002-0000-0000-0001-000000000001', 6, 'fill_blank', '{"text": "I ride my ___ to school every day. (bicicleta en inglés)"}'::jsonb, '{"text": "bike", "accepted": ["bike"]}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0001-0007-000000000001', '00000002-0000-0000-0001-000000000001', 7, 'multiple_choice', '{"text": "¿Cuál par de palabras muestra la diferencia entre O corta y O larga?"}'::jsonb, '{"text": "hot /hɒt/ (O corta) — home /hoʊm/ (O larga)"}'::jsonb, '["cat /kæt/ — cake /keɪk/ (estas son vocales A, no O)", "sit /sɪt/ — bike /baɪk/ (estas son vocales I, no O)", "cup /kʌp/ — cube /kjuːb/ (estas son vocales U, no O)"]'::jsonb, '{"es": "La O en ''hot'' es corta /ɒ/ — sílaba cerrada. La O en ''home'' es larga /oʊ/ gracias a la E final silenciosa (magic E). Esta regla aplica a todas las vocales."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0001-0008-000000000001', '00000002-0000-0000-0001-000000000001', 8, 'fill_blank', '{"text": "I drink coffee from a ___. (taza — vocal U corta /ʌ/ como en ''cup'')"}'::jsonb, '{"text": "cup", "accepted": ["cup"]}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0002-0001-000000000001', '00000002-0000-0000-0001-000000000002', 1, 'flashcard', '{"text": "think", "subtext": "Contiene el sonido TH /θ/ — fuerte, sin vibración"}'::jsonb, '{"text": "pensar", "phonetic": "/θɪŋk/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0002-0002-000000000001', '00000002-0000-0000-0001-000000000002', 2, 'flashcard', '{"text": "water", "subtext": "Contiene el sonido W /w/ — labios redondeados"}'::jsonb, '{"text": "agua", "phonetic": "/ˈwɔːtər/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0002-0003-000000000001', '00000002-0000-0000-0001-000000000002', 3, 'multiple_choice', '{"text": "¿Cómo se produce el sonido TH en ''the'' y ''this''?"}'::jsonb, '{"text": "Colocando la lengua entre los dientes y haciendo vibrar las cuerdas vocales"}'::jsonb, '["Pronunciando como la S española fuerte", "Pronunciando como la D española", "Colocando la lengua entre los dientes sin hacer vibrar las cuerdas vocales"]'::jsonb, '{"es": "El TH en ''the'' y ''this'' es el TH ''voiced'' (sonoro). La lengua va entre los dientes Y las cuerdas vocales vibran. Es diferente del TH en ''think'' que es ''voiceless'' (sordo)."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0002-0004-000000000001', '00000002-0000-0000-0001-000000000002', 4, 'multiple_choice', '{"text": "¿Cuál es la diferencia principal entre V y B en inglés?"}'::jsonb, '{"text": "La V se produce con los dientes superiores en el labio inferior; la B junta los dos labios"}'::jsonb, '["La V y la B suenan igual en inglés, como en español", "La B se produce con los dientes superiores en el labio inferior", "La V es más fuerte y la B es más suave, pero ambas usan los labios"]'::jsonb, '{"es": "En inglés, V y B son sonidos completamente distintos. La V /v/ es labiodental (dientes + labio inferior). La B /b/ es bilabial (ambos labios juntos). En español no existe esta distinción."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0002-0005-000000000001', '00000002-0000-0000-0001-000000000002', 5, 'fill_blank', '{"text": "I drink ___ every morning. (agua)"}'::jsonb, '{"text": "water", "accepted": ["water"]}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0002-0006-000000000001', '00000002-0000-0000-0001-000000000002', 6, 'fill_blank', '{"text": "I ___ you are very kind. (pensar/creer — usa el presente simple)"}'::jsonb, '{"text": "think", "accepted": ["think"]}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0002-0007-000000000001', '00000002-0000-0000-0001-000000000002', 7, 'multiple_choice', '{"text": "¿Cuál pronunciación de ''very'' es CORRECTA en inglés?"}'::jsonb, '{"text": "/ˈveri/ — V labiodental: dientes superiores en el labio inferior"}'::jsonb, '["/ˈberi/ — incorrecto: eso suena como ''berry'' (arándano)", "/ˈweri/ — incorrecto: eso sería ''weary'' (cansado)", "/ˈferi/ — incorrecto: eso sería ''ferry'' (transbordador)"]'::jsonb, '{"es": "La V inglesa es labiodental: los dientes superiores tocan el labio inferior y el aire vibra. Si dices ''very'' como ''bery'', suenas como si dijeras ''berry'' (un tipo de fruta pequeña) — ¡son palabras completamente distintas!"}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0002-0008-000000000001', '00000002-0000-0000-0001-000000000002', 8, 'fill_blank', '{"text": "She is ___ kind and helpful. (muy — contiene el sonido V)"}'::jsonb, '{"text": "very", "accepted": ["very"]}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0003-0001-000000000001', '00000002-0000-0000-0001-000000000003', 1, 'flashcard', '{"text": "How do you spell that?", "subtext": "Frase para pedir que alguien deletree algo"}'::jsonb, '{"text": "¿Cómo se deletrea eso?", "phonetic": "/haʊ duː juː spɛl ðæt/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0003-0002-000000000001', '00000002-0000-0000-0001-000000000003', 2, 'flashcard', '{"text": "W", "subtext": "Nombre de esta letra del alfabeto inglés"}'::jsonb, '{"text": "double-you", "phonetic": "/ˈdʌbəl juː/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0003-0003-000000000001', '00000002-0000-0000-0001-000000000003', 3, 'multiple_choice', '{"text": "¿Cómo se llama la letra ''J'' en inglés?"}'::jsonb, '{"text": "Jay /dʒeɪ/"}'::jsonb, '["Jot /dʒɒt/", "Yee /jiː/", "Gee /dʒiː/"]'::jsonb, '{"es": "La letra J en inglés se llama ''Jay'' y se pronuncia /dʒeɪ/. No se pronuncia como la J española. La letra G se llama ''Gee'' /dʒiː/, que suena parecido pero es diferente."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0003-0004-000000000001', '00000002-0000-0000-0001-000000000003', 4, 'multiple_choice', '{"text": "¿Cómo deletreas la palabra HELLO en inglés?"}'::jsonb, '{"text": "H-E-L-L-O"}'::jsonb, '["H-A-L-L-O", "H-E-L-O", "H-I-L-L-O"]'::jsonb, '{"es": "HELLO se deletrea H-E-L-L-O. Tiene doble L. Es una de las primeras palabras que debes aprender a deletrear en inglés."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0003-0005-000000000001', '00000002-0000-0000-0001-000000000003', 5, 'fill_blank', '{"text": "My name is Maria. It''s spelled M-A-R-___-A."}'::jsonb, '{"text": "I", "accepted": ["I", "i"]}'::jsonb, NULL, NULL);
