('00000003-0001-0003-0007-000000000001', '00000002-0000-0000-0001-000000000003', 7, 'translation', '{"text": "¿Cómo se escribe tu nombre?"}'::jsonb, '{"text": "How do you spell your name?", "accepted": ["How do you spell your name", "Can you spell your name?", "How is your name spelled?"]}'::jsonb, NULL, NULL);
