INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0004-0002-000000000001', '00000002-0000-0000-0001-000000000004', 2, 'flashcard', '{"text": "singing", "subtext": "Contiene el sonido NG /ŋ/ al final"}'::jsonb, '{"text": "cantando", "phonetic": "/ˈsɪŋɪŋ/"}'::jsonb, NULL, NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0004-0003-000000000001', '00000002-0000-0000-0001-000000000004', 3, 'multiple_choice', '{"text": "¿Cómo se produce el sonido SH en inglés (como en ''shop'')?"}'::jsonb, '{"text": "Labios ligeramente hacia adelante, lengua cerca del paladar, soplando aire suave"}'::jsonb, '["Igual que la S española pero más fuerte", "Igual que la CH española", "Juntando los labios completamente y soplando"]'::jsonb, '{"es": "El sonido SH /ʃ/ se produce con los labios ligeramente protruidos (hacia adelante) y la lengua elevada cerca del paladar duro, soplando un chorro de aire continuo. No es S ni CH."}'::jsonb);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0001-0004-0004-000000000001', '00000002-0000-0000-0001-000000000004', 4, 'multiple_choice', '{"text": "¿En cuál de estas palabras la R inglesa es más diferente a la R española?"}'::jsonb, '{"text": "butter /ˈbʌtər/ — la R al final es suave y no vibra"}'::jsonb, '["run /rʌn/ — la R inicial", "arrive /əˈraɪv/ — la R en medio", "Todas tienen exactamente la misma R española vibrante"]'::jsonb, '{"es": "La R inglesa nunca vibra como la R española. En ''butter'', la R final es especialmente diferente — es casi una vocal, muy suave. Pero en todas las posiciones, la R inglesa es diferente a la española."}'::jsonb);
