('00000003-0001-0004-0005-000000000001', '00000002-0000-0000-0001-000000000004', 5, 'fill_blank', '{"text": "I am ___ a song in the morning. (cantando)"}'::jsonb, '{"text": "singing", "accepted": ["singing"]}'::jsonb, NULL, NULL);
